def shoot(rounds):
    pete_score = 0
    phil_score = 0
    for scores, smoke in rounds:
        multiplier = 2 if smoke else 1
        pete_score += scores['P1'].count('X') * multiplier
        phil_score += scores['P2'].count('X') * multiplier
    if pete_score > phil_score:
        return 'Pete Wins!'
    elif phil_score > pete_score:
        return 'Phil Wins!'
    else:
        return 'Draw!'
